/* eslint-disable no-new */

'use strict';

// MODULES //

var tape = require( 'tape' );
var isndarrayLikeWithDataType = require( '@stdlib/assert/is-ndarray-like-with-data-type' );
var isEqualInt8Array = require( '@stdlib/assert/is-equal-int8array' );
var isReadOnly = require( '@stdlib/ndarray/base/assert/is-read-only' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Int8Array = require( '@stdlib/array/int8' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var numel = require( '@stdlib/ndarray/numel' );
var getOrder = require( '@stdlib/ndarray/order' );
var Int8Tensor0D = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Int8Tensor0D, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			new Int8Tensor0D( value );
		};
	}
});

