tape( 'the function returns a zero-dimensional ndarray', function test( t ) {
	var arr;

	arr = new Int8Tensor0D();
	t.strictEqual( isndarrayLikeWithDataType( arr, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( arr ), 1, 'returns expected value' );

	arr = new Int8Tensor0D( {} );
	t.strictEqual( isndarrayLikeWithDataType( arr, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( arr ), 1, 'returns expected value' );

	t.end();
});

tape( 'the function returns a zero-dimensional ndarray (scalar)', function test( t ) {
	var arr;
	var out;

	arr = [ 1 ];

	out = new Int8Tensor0D( arr[ 0 ] );
	t.strictEqual( isndarrayLikeWithDataType( out, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( out ), 1, 'returns expected value' );
	t.strictEqual( isEqualInt8Array( getData( out ), new Int8Array( arr ) ), true, 'returns expected value' );

	out = new Int8Tensor0D( arr[ 0 ], {} );
	t.strictEqual( isndarrayLikeWithDataType( out, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( out ), 1, 'returns expected value' );
	t.strictEqual( isEqualInt8Array( getData( out ), new Int8Array( arr ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a zero-dimensional ndarray (arraybuffer)', function test( t ) {
	var buf;
	var out;

	buf = new ArrayBuffer( 1 );

	out = new Int8Tensor0D( buf );
	t.strictEqual( isndarrayLikeWithDataType( out, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( out ), 1, 'returns expected value' );
	t.strictEqual( isEqualInt8Array( getData( out ), new Int8Array( buf, 0, 1 ) ), true, 'returns expected value' );

	out = new Int8Tensor0D( buf, {} );
	t.strictEqual( isndarrayLikeWithDataType( out, 'int8' ), true, 'returns expected value' );
	t.strictEqual( numel( out ), 1, 'returns expected value' );
	t.strictEqual( isEqualInt8Array( getData( out ), new Int8Array( buf, 0, 1 ) ), true, 'returns expected value' );

	t.end();
});

